DNA = ""

# Peça para o usuarui entrar com o padrão procurado e caso exista esse padrão, diga quantas vezes ele se repete

padrao = input("Qual o Padrao que voce deseja ver quantas vezes aparece meu lindo: ")
possuiPadrao = padrao.upper() in DNA

if (possuiPadrao) :
    print("Padrao Encontrado!!!")
    qtd_padrao = DNA.count(padrao.upper())
    print(f"o Padrão {padrao} se repete {qtd_padrao} ")
    primeira_ocorrencia =DNA.find(padrao.upper())
    print(f"primeira_ocorrencia do Padrão {primeira_ocorrencia}")
else:
    print("Padrão Não Encontrado!!!")

